static R65HotMap map;
static int reference(uint32_t pc) {
  for(unsigned i=0;i<sizeof(entries)/sizeof(entries[0]);++i)
    if(entries[i]==pc) return (int)i;
  return -1;
}
int main(void) {
  memset(&map,0,sizeof(map));
  for(unsigned i=0;i<sizeof(entries)/sizeof(entries[0]);++i) {
    int present=r65_hot_insert(&map,entries[i],i);
    assert(present>=0);
  }
  unsigned checks=0,hot=0;
  for(unsigned page=0;page<R65_HOT_PAGES;page++) {
    uint32_t base=page==0?0x808400u:page==1?0x80be00u:
                 page==2?0x81f100u:page==3?0x829800u:0x829900u;
    for(unsigned i=0;i<256;i++) {
      uint32_t pc=base|i;
      assert(r65_hot_lookup(&map,pc)==reference(pc));
      checks++;hot++;
    }
  }
  // Exhaustively check all offsets in the three heavily executing ROM banks.
  for(uint32_t bank=0x80;bank<=0x82;bank++)for(unsigned off=0;off<65536;off++) {
    uint32_t pc=(bank<<16)|off;
    int idx=r65_hot_lookup(&map,pc);
    if(r65_hot_page(pc)<0)assert(idx==-2);
    else assert(idx==reference(pc));
    checks++;
  }
  // Empty, zero, cross-page and duplicate behavior must be conservative.
  assert(r65_hot_lookup(&map,0)==-2);
  assert(r65_hot_lookup(&map,0x7e9930u)==-2);
  assert(r65_hot_lookup(&map,0x839930u)==-2);
  assert(r65_hot_lookup(&map,0x829a30u)==-2);
  assert(r65_hot_insert(&map,0x829930u,65535u)==-1);
  unsigned dup=0;
  for(unsigned i=0;i<sizeof(entries)/sizeof(entries[0]);i++) {
    if(r65_hot_page(entries[i])>=0){assert(r65_hot_insert(&map,entries[i],i)==-1);dup++;}
  }
  printf("PASS R65 direct lookup exhaustive %u PCs, %u hot page offsets, %u populated hot slots; registered test entries=%zu\n",checks,hot,dup,sizeof(entries)/sizeof(entries[0]));
  return 0;
}
